{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `MapleMonk.Zouk_Founders_Dashboard` AS WITH PnL AS ( SELECT Date, Marketplace_Segment, COLLECTION, PRODUCT_CATEGORY, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(Return_GST, 0)) AS Net_Revenue, -1 * (SUM(IFNULL(cogs, 0)) - SUM(IFNULL(return_cogs, 0))) AS COGS, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(return_gst, 0)) - SUM(IFNULL(CHANNEL_MARGIN, 0)) - SUM(IFNULL(cogs, 0)) + SUM(IFNULL(return_cogs, 0)) - SUM(IFNULL(offline_store_cost, 0)) - SUM(IFNULL(LOGISTICS_COST, 0)) + SUM(IFNULL(return_logistics_cost, 0)) - SUM(IFNULL(spend, 0)) - SUM(IFNULL(other_performance_spend, 0)) + SUM(IFNULL(brand_spend, 0)) AS CM2, SUM(IFNULL(brand_spend, 0)) - SUM(IFNULL(spend, 0)) - SUM(IFNULL(other_performance_spend, 0)) AS Performance_Marketing_Spends, SUM(IFNULL(BAU_MRP_SALES, 0)) - IFNULL(SUM(IFNULL(BAU_DISCOUNT, 0)), 0) - SUM(IFNULL(return_mrp_sales, 0)) AS MRP_Sales FROM `MapleMonk.zouk_pandl` GROUP BY Date, Marketplace_Segment, COLLECTION, PRODUCT_CATEGORY ), PnL_Summary AS ( SELECT Date, SUM(Net_Revenue) AS Net_Revenue, SUM(COGS) AS COGS, SUM(CM2) AS CM2, SUM(Performance_Marketing_Spends) AS Performance_Marketing_Spends, SUM(MRP_Sales) AS MRP_Sales FROM PnL GROUP BY Date ), Metrics AS ( SELECT Date, SUM(CASE WHEN LOWER(Marketplace_Segment) LIKE \'%quick-commerce%\' THEN Net_Revenue ELSE 0 END) AS Net_Revenue_QCommerce, SUM(CASE WHEN LOWER(Marketplace_Segment) LIKE \'%e-commerce%\' THEN Net_Revenue ELSE 0 END) AS Net_Revenue_ECommerce, SUM(CASE WHEN LOWER(Marketplace_Segment) LIKE \'d2c\' THEN Net_Revenue ELSE 0 END) AS Net_Revenue_DTC, SUM(CASE WHEN LOWER(Marketplace_Segment) LIKE \'offline\' THEN Net_Revenue ELSE 0 END) AS Net_Revenue_Offline, SUM(CASE WHEN (COLLECTION IS NULL OR (LOWER(collection) NOT LIKE \'%footwear%\' AND LOWER(collection) NOT LIKE \'%backpack%\'AND LOWER(collection) NOT LIKE \'%luggage%\')) THEN Net_Revenue ELSE 0 END) AS Net_Revenue_Bags, SUM(CASE WHEN LOWER(collection) LIKE \'backpack\' THEN Net_Revenue ELSE 0 END) AS Net_Revenue_Backpack, SUM(CASE WHEN LOWER(collection) LIKE \'%luggage%\' THEN Net_Revenue ELSE 0 END) AS Net_Revenue_Trolley_Duffel, SUM(CASE WHEN LOWER(collection) LIKE \'footwear\' THEN Net_Revenue ELSE 0 END) AS Net_Revenue_Others, SUM(CASE WHEN LOWER(collection) LIKE \'%men%\' THEN Net_Revenue ELSE 0 END) AS Net_Revenue_Mens_Collection, SUM(CASE WHEN LOWER(collection) LIKE \'%rhea%\' THEN Net_Revenue ELSE 0 END) AS Net_Revenue_Rhea_Kapoor_Collection, SUM(CASE WHEN LOWER(Product_Category) LIKE ANY (\'kyra flap wallet\',\'arika zipper wallet\',\'konkona city satchel bag\',\"mother\'s bag\",\'beyond basic sling bag\',\'handbag\',\"teacher\'s bag\") THEN Net_Revenue ELSE 0 END) AS Net_Revenue_Low_DRR FROM PnL GROUP BY Date ), Dispatch AS ( SELECT SAFE.PARSE_DATE(\'%m/%d/%Y\', Date) AS Date, SUM(CASE WHEN LOWER(Status) LIKE \'%full%\' THEN SAFE_CAST(Actual_Quantity AS INT64) ELSE 0 END) AS Full_Kits_Dispatched FROM `MapleMonk.Zouk_RM_Dispatch` GROUP BY Date ), Inward AS ( SELECT SAFE.PARSE_DATE(\'%m/%d/%Y\', Date) AS Date, SUM(SAFE_CAST(Inward_Quantity AS INT64)) AS Inward_Quantity FROM `MapleMonk.Inward_Data` GROUP BY Date ) SELECT Date, SUM(Net_Revenue) AS Net_Revenue, SUM(COGS) AS COGS, SUM(Performance_Marketing_Spends) AS Performance_Marketing_Spends, SUM(CM2) AS CM2, SUM(MRP_Sales) AS MRP_Sales, SUM(Net_Revenue_Bags) AS Net_Revenue_Bags, SUM(Net_Revenue_Backpack) AS Net_Revenue_Backpacks, SUM(Net_Revenue_Trolley_Duffel) AS Net_Revenue_Trolley_Duffel, SUM(Net_Revenue_Others) AS Net_Revenue_Others, SUM(Net_Revenue_QCommerce) AS Net_Revenue_QCommerce, SUM(Net_Revenue_ECommerce) AS Net_Revenue_ECommerce, SUM(Net_Revenue_DTC) AS Net_Revenue_D2C, SUM(Net_Revenue_Offline) AS Net_Revenue_Offline, SUM(Net_Revenue_Mens_Collection) AS Net_Revenue_Mens_Collection, SUM(Net_Revenue_Rhea_Kapoor_Collection) AS Net_Revenue_Rhea_Collection, SUM(Net_Revenue_Low_DRR) AS Net_Revenue_Low_DRR, SUM(Inward_Quantity) AS Inward_Quantity, SUM(Full_Kits_Dispatched) AS Full_Kits_Dispatched FROM ( SELECT COALESCE(p.Date, m.Date, d.Date, i.Date) AS Date, p.Net_Revenue, p.COGS, p.Performance_Marketing_Spends, p.CM2, p.MRP_Sales, m.Net_Revenue_Bags, m.Net_Revenue_Backpack, m.Net_Revenue_Trolley_Duffel, m.Net_Revenue_Others, m.Net_Revenue_QCommerce, m.Net_Revenue_ECommerce, m.Net_Revenue_DTC, m.Net_Revenue_Offline, m.Net_Revenue_Mens_Collection, m.Net_Revenue_Rhea_Kapoor_Collection, m.Net_Revenue_Low_DRR, i.Inward_Quantity, d.Full_Kits_Dispatched FROM PnL_Summary p FULL OUTER JOIN Metrics m ON p.Date = m.Date FULL OUTER JOIN Dispatch d ON COALESCE(p.Date, m.Date) = d.Date FULL OUTER JOIN Inward i ON COALESCE(p.Date, m.Date, d.Date) = i.Date ) AS joined GROUP BY Date ORDER BY Date;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            